local ZModsLocalizationCore = (function ()
-- Portable localization core, API 1 revision 1. Lua 5.1, no engine/UI globals.
-- Each consumer owns its catalog and supplies a language reader. No registry,
-- storage, timers, event handlers, font changes, or global localization hooks.
local Core = { APIVersion = 1, Revision = 1 }

Core.Create = function ( catalogs, readLanguage )
    local L = { Catalogs = type( catalogs ) == "table" and catalogs or {} }
    local aliases = {
        ["pt-br"] = "pt-BR", ["zh-cn"] = "zh-CN", ["zh-tw"] = "zh-TW"
    }
    -- This core handles canonical locale IDs only. Game enum/SKU aliases
    -- belong to the port adapter, not to another mod's catalog.
    L.Normalize = function ( value )
        if type( value ) ~= "string" then return nil end
        if value == "" then return nil end
        value = string.lower( value )
        return aliases[value] or value
    end
    L.Language = function ()
        if type( readLanguage ) == "function" then
            local ok, value = pcall( readLanguage )
            if ok then return L.Normalize( value ) or "en" end
        end
        return "en"
    end
    L.Text = function ( value )
        if value == nil then return "" end
        value = tostring( value )
        local catalog = L.Catalogs[L.Language()]
        local translation = type( catalog ) == "table" and catalog[value] or nil
        if type( translation ) == "string" and translation ~= "" then return translation end
        local english = L.Catalogs.en
        local fallback = type( english ) == "table" and english[value] or nil
        return type( fallback ) == "string" and fallback ~= "" and fallback or value
    end
    L.Format = function ( source, values )
        -- Function replacement preserves literal percent signs. Substituted
        -- text is never parsed again, so braces in player-supplied values are safe.
        return ( string.gsub( L.Text( source ), "{([%w_]+)}", function ( key )
            local value = nil
            if type( values ) == "table" then value = values[key] end
            return value ~= nil and tostring( value ) or ( "{" .. key .. "}" )
        end ) )
    end
    L.Length = function ( value )
        -- UTF-8 leading-byte count, not font measurement or RTL shaping.
        local text = tostring( value or "" )
        local count = 0
        for index = 1, #text do
            local byte = string.byte( text, index )
            if byte < 128 or byte >= 192 then count = count + 1 end
        end
        return count
    end
    return L
end

return Core
end)()
local ZModsLanguageAdapter = (function ()
-- Shared T6/T7 language reader. Engine objects are injected by the consumer.
local Adapter = { APIVersion = 1, Revision = 1 }
local numeric = {
    [0] = "en", [1] = "fr", [2] = "fr", [3] = "de", [4] = "de",
    [5] = "it", [6] = "es", [7] = "en", [8] = "ru", [9] = "pl",
    [10] = "ko", [11] = "ja", [12] = "cs", [13] = "ja", [14] = "pt-BR",
    [15] = "es", [16] = "ar", [17] = "zh-TW", [18] = "zh-CN",
    [19] = "en", [20] = "en", [21] = "he", [22] = "en"
}
local aliases = {
    english = "en", british = "en", french = "fr", frenchcanadian = "fr",
    german = "de", austrian = "de", italian = "it", spanish = "es",
    mexicanspanish = "es", russian = "ru", polish = "pl", korean = "ko",
    japanese = "ja", fulljapanese = "ja", czech = "cs", portuguese = "pt-BR",
    brazilian = "pt-BR", arabic = "ar", traditionalchinese = "zh-TW",
    simplifiedchinese = "zh-CN", englishgerman = "en", englishjapanese = "en",
    englisharabic = "en", hebrew = "he", ["pt-br"] = "pt-BR",
    ["zh-tw"] = "zh-TW", ["zh-cn"] = "zh-CN"
}
Adapter.Create = function ( core, catalogs, readEnvironment )
    local normalize = function ( value )
        if type( value ) == "number" then return numeric[value] end
        if type( value ) ~= "string" then return nil end
        local number = tonumber( value )
        if number ~= nil then return numeric[number] end
        value = string.lower( value )
        return aliases[value] or ( type( catalogs ) == "table" and catalogs[value] ~= nil and value or nil )
    end
    local read = function ()
        local engine, dvars = readEnvironment()
        -- T7 invents callable NullFunctions for absent Engine keys. Enumerate
        -- real exports; BO3's compiler does not accept the rawget builtin.
        local getLanguage = nil
        if type( engine ) == "table" then
            for key, value in pairs( engine ) do
                if key == "GetLanguage" then getLanguage = value; break end
            end
        end
        if type( getLanguage ) == "function" then
            local ok, value = pcall( getLanguage )
            if ok then
                local language = normalize( value )
                if language ~= nil then return language end
            end
        end
        if dvars ~= nil then
            local ok, value = pcall( function () return dvars.loc_language:get() end )
            if ok then
                local language = normalize( value )
                if language ~= nil then return language end
            end
        end
        return "en"
    end
    local instance = core.Create( catalogs, read )
    instance.NormalizeGameLanguage = normalize
    return instance
end
return Adapter
end)()
-- ZTweaks-owned facade. Portable modules have no CoD or owner dependency.
local L = CoD.ZTweaksLocalization
local instance = ZModsLanguageAdapter.Create( ZModsLocalizationCore, L.Catalogs, function () return Engine, Dvar end )
L.Normalize = instance.NormalizeGameLanguage
L.Language = instance.Language
L.Text = instance.Text
L.Format = instance.Format
L.Length = instance.Length
L.CoreAPIVersion = ZModsLocalizationCore.APIVersion
L.CoreRevision = ZModsLocalizationCore.Revision
L.AdapterAPIVersion = ZModsLanguageAdapter.APIVersion
L.AdapterRevision = ZModsLanguageAdapter.Revision
-- Owner-localizer presentation ABI v1. Resolve by stable identity, never by
-- the current position of a choice (CHANGED rows deliberately collapse their
-- values). Unknown words are returned unchanged so the renderer may try its
-- closed shell vocabulary without borrowing another owner's catalog.
local identities = ( CoD.ZTweaksSettings or {} ).LocalizationIdentities or {}
local reverse = {}
for key, english in pairs( identities ) do
    if reverse[english] == nil then reverse[english] = key
    elseif reverse[english] ~= key then reverse[english] = false end
end
local function identityText( key, english )
    if type( key ) == "string" and identities[key] == english then return L.Text( english ) end
    return nil
end
L.Provide = function ( english, context )
    if type( english ) ~= "string" or english == "" then return english end
    local row = type( context ) == "table" and context.row or nil
    local tab = type( context ) == "table" and context.tab or nil
    local found = nil
    if type( row ) == "table" then
        found = identityText( row.labelKey, english ) or identityText( row.hintKey, english )
            or identityText( row.boundaryKey, english ) or identityText( row.scopeKey, english )
        if found ~= nil then return found end
        if type( row.choiceKeys ) == "table" then
            for _, key in ipairs( row.choiceKeys ) do
                found = identityText( key, english )
                if found ~= nil then return found end
            end
        end
        if type( row.dvar ) == "string" then
            found = identityText( "setting." .. row.dvar, english ) or identityText( "hint." .. row.dvar, english )
            if found ~= nil then return found end
            if type( row.values ) == "table" then
                for _, value in ipairs( row.values ) do
                    found = identityText( "choice." .. row.dvar .. "." .. tostring( value ), english )
                    if found ~= nil then return found end
                end
            end
        end
    end
    if type( tab ) == "table" then
        found = identityText( tab.labelKey, english ) or identityText( tab.hintKey, english )
        if found == nil and type( tab.id ) == "string" then
            found = identityText( "page." .. tab.id, english ) or identityText( "page." .. tab.id .. ".hint", english )
        end
        if found ~= nil then return found end
    end
    local key = reverse[english]
    if type( key ) == "string" then return L.Text( english ) end
    return english
end
-- Registration is intentionally outside both portable modules.
CoD.ZBundleSettings = CoD.ZBundleSettings or {}
CoD.ZBundleSettings.Localizers = CoD.ZBundleSettings.Localizers or {}
CoD.ZBundleSettings.Localizers.ztweaks = { version = 1, text = L.Provide }
-- Client-local warning presentation. No gameplay state, persistence or clientfields.
local L = CoD.ZTweaksLocalization
local N = { owners = {} }
L.Notices = N

-- BO3's stock GSC has no SetClientDvar external. The HUD receives only the
-- host's one-bit Knife Lunge command and applies it on this client. The marker
-- lets a later frontend Lua load repair an interrupted match without touching
-- a value that some other owner has already changed.
N.KnifeRestore = function ()
    if Engine.DvarString == nil or Engine.SetDvar == nil then return end
    local ok, owned = pcall( Engine.DvarString, nil, "zt_knife_lunge_client_owned" )
    if not ok or tostring( owned ) ~= "1" then return end
    local currentOk, current = pcall( Engine.DvarString, nil, "aim_automelee_enabled" )
    if currentOk and tostring( current ) == "0" then
        pcall( Engine.SetDvar, "aim_automelee_enabled", 1 )
    end
    pcall( Engine.SetDvar, "zt_knife_lunge_client_owned", 0 )
end

N.KnifeCommand = function ( value )
    if Engine.DvarString == nil or Engine.SetDvar == nil then return end
    if tonumber( value ) == 1 then N.KnifeRestore(); return end
    if tonumber( value ) ~= 0 then return end
    local ok, current = pcall( Engine.DvarString, nil, "aim_automelee_enabled" )
    if not ok or tostring( current ) ~= "1" then return end
    local applied, result = pcall( Engine.SetDvar, "aim_automelee_enabled", 0 )
    if applied and result ~= false then
        pcall( Engine.SetDvar, "zt_knife_lunge_client_owned", 1 )
    end
end

N.Message = function ( code )
    if code == 1 then
        return L.Text( "ZTweaks: character preferences skipped; a temporary player state remained active." )
    end
    local feature = math.floor( code / 512 )
    local reason = code % 512
    local name = L.NoticeNames[feature]
    local why = L.NoticeReasons[reason]
    if name == nil or why == nil then return nil end
    return L.Format( "ZTweaks: {feature} disabled - {reason}", {
        feature = L.Text( L.ReportLabels[name] or name ), reason = L.Text( why )
    } )
end

N.Accept = function ( owner, signature, token, code )
    signature, token, code = tonumber( signature ), tonumber( token ), tonumber( code )
    if signature ~= L.NoticeSignature or token == nil or code == nil
        or token < 1 or token ~= math.floor( token ) or code ~= math.floor( code ) then return false end
    local message = N.Message( code )
    if message == nil then return false end
    if owner.seen[token] ~= nil then
        if owner.seen[token] ~= code then return false end
    else
        -- Refuse an overflowing queue so the sender can use its native fallback.
        if #owner.queue >= 32 then return false end
        owner.seen[token] = code
        owner.order[#owner.order + 1] = token
        if #owner.order > 256 then owner.seen[table.remove( owner.order, 1 )] = nil end
        owner.queue[#owner.queue + 1] = message
    end
    pcall( Engine.SendMenuResponse, owner.controller, owner.port == "t7" and "StartMenu_Main" or "class",
        "zt_notice|" .. tostring( token ) )
    return true
end

N.Attach = function ( menu, controller, port )
    if type( controller ) ~= "number" or controller < 0 then return end
    if menu.ztNoticeOwner ~= nil then menu.ztNoticeOwner.element:close() end
    local element = LUI.UIElement.new()
    element:setLeftRight( true, true, 0, 0 )
    element:setTopBottom( true, true, 0, 0 )
    menu:addElement( element )
    local owner = { element = element, controller = controller, port = port, queue = {}, seen = {}, order = {}, ticks = 0 }
    if port == "t6" then
        owner.dvar = "zt_ui_notice_" .. tostring( Engine.GetClientNum( controller ) )
        -- Session-only mailbox: discard the last match's packet. The bounded
        -- sender retries a packet that arrived before this HUD existed.
        Engine.SetDvar( owner.dvar, "" )
    end
    menu.ztNoticeOwner = owner
    local label = LUI.UIText.new()
    label:setLeftRight( false, false, -290, 290 )
    label:setTopBottom( true, false, 135, 155 )
    label:setFont( port == "t7" and CoD.fonts.default or CoD.fonts.Default )
    label:setText( "" )
    element:addElement( label )
    element:registerEventHandler( "zt_notice_tick", function ()
        if port == "t6" then
            local value = UIExpression.DvarString( nil, owner.dvar ) or ""
            if value ~= owner.last then
                local signature, token, code = string.match( value, "^(%d+)|(%d+)|(%d+)|%d+$" )
                -- Do not consume a full queue's packet; retry after space appears.
                if signature ~= nil and N.Accept( owner, signature, token, code ) then owner.last = value end
            end
        end
        if owner.ticks > 0 then owner.ticks = owner.ticks - 1 end
        if owner.ticks == 0 then
            local nextMessage = table.remove( owner.queue, 1 )
            label:setText( nextMessage or "" )
            if nextMessage ~= nil then owner.ticks = 24 end
        end
    end )
    element:addElement( LUI.UITimer.new( 250, "zt_notice_tick", false, element ) )
    if port == "t7" then
        element:subscribeToGlobalModel( controller, "PerController", "scriptNotify", function ( model )
            local event = Engine.GetModelValue( model )
            if event == "ztKnifeLunge" then
                local data = CoD.GetScriptNotifyData( model )
                if data ~= nil then N.KnifeCommand( data[1] ) end
                return
            end
            if event ~= "ztLocalizedNotice" then return end
            local data = CoD.GetScriptNotifyData( model )
            if data ~= nil then N.Accept( owner, data[1], data[2], data[3] ) end
        end )
    end
end

N.Install = function ( port )
    if port == "t7" and Engine.GetCurrentMap ~= nil then
        local ok, map = pcall( Engine.GetCurrentMap )
        if ok and map == "core_frontend" then N.KnifeRestore() end
    end
    -- Install only after the owning settings module loads. Wrap an instance's
    -- lifecycle, not global Engine text functions or unrelated stock menus.
    if CoD.ztNoticeHookVersion == 1 then return end
    CoD.ztNoticeHookVersion = 1
    if port == "t6" then
        local previous = CoD.Menu.NewFromState
        CoD.Menu.NewFromState = function ( name, ... )
            local menu = previous( name, ... )
            if name ~= "HUD" then return menu end
            local register = menu.registerEventHandler
            menu.registerEventHandler = function ( self, event, handler )
                if event == "first_snapshot" then
                    return register( self, event, function ( hud, data )
                        local result = handler( hud, data )
                        -- Stock removes all children at first_snapshot/migration.
                        pcall( CoD.ZTweaksLocalization.Notices.Attach, hud, data.controller, port )
                        return result
                    end )
                end
                return register( self, event, handler )
            end
            return menu
        end
    else
        local previous = CoD.Menu.NewForUIEditor
        CoD.Menu.NewForUIEditor = function ( name, ... )
            local menu = previous( name, ... )
            if name ~= "T7Hud_ZM" and string.sub( name or "", 1, 8 ) ~= "T7Hud_zm" then return menu end
            -- Stock sets the actual controller after construction. Never assume
            -- the primary controller for a secondary player's warning/ACK.
            local setOwner = menu.setOwner
            menu.setOwner = function ( self, controller )
                local result = setOwner( self, controller )
                pcall( CoD.ZTweaksLocalization.Notices.Attach, self, controller, port )
                return result
            end
            return menu
        end
    end
end
